\label{Thilliez-Beurlingcase}
Let $\M$ be a weight sequence with $\ga(\M)>0$ and that satisfies $\sm$, and let $0<r<\ga(\M)$ be given.
	Then, the Borel map $\widetilde{\mathcal{B}}\colon \widetilde{\mathcal{A}}^u_{(\M)}(S_{r})\to\C[[z]]_{(\M)}$ is surjective, and so $(0,\ga(\M))\subset\widetilde{S}_{(\M)}^u$.

\label{teorcondicion3caracterizacion}
Let $\M$ be a strongly regular sequence. Then
$d_{\M}(t)$ verifies condition~(\ref{OA3:1}) if, and only if,
\begin{equation}\label{limit.logmp.over.logp.omega}
    \lim_{p\ri \oo} \frac{\log (m_p)}{\log(p)}=\o(\M).
\end{equation}
